<x-public-layout title="{{ $tournament->name }} · Live Draft">
    <main class="container py-4 py-lg-5" x-data="publicDraft(@js($state), @js(route('public.draft.state', $tournament)))" x-init="init()">
        <div class="d-flex flex-column flex-lg-row align-items-lg-end justify-content-between gap-3 mb-4"><div><p class="cricket-kicker mb-2">Live tournament coverage</p><h1 class="display-6 fw-bold mb-2">{{ $tournament->name }}</h1><p class="text-secondary mb-0">Follow the timer and every selected player as the draft moves.</p></div><div class="small text-secondary">Revision <span class="fw-bold text-dark" x-text="state.revision"></span> · Server time <span class="fw-bold text-dark">{{ now()->format('H:i') }}</span></div></div>
        <div class="row g-4 mb-4"><div class="col-xl-8"><div class="cricket-pitch-panel p-4 p-lg-5"><div class="d-flex align-items-start justify-content-between gap-3 mb-5"><div><p class="cricket-kicker mb-2">Current pick</p><div class="small text-white-50 mb-2" x-text="state.current_round ? `Round ${state.current_round} · Pick ${state.current_pick_number ?? '—'}` : 'Waiting for the next assignment'"></div><h2 class="display-5 fw-bold mb-1" x-text="state.current_team?.name ?? 'Waiting for admin'"></h2><div class="text-white-50" x-text="state.status === 'expired' ? 'Timer paused — admin action required' : 'On the clock now'"></div></div><span class="badge" style="background:var(--cricket-lime);color:var(--cricket-pitch-deep);" x-text="state.status"></span></div><div class="row align-items-end"><div class="col-md-7"><div class="small text-white-50 mb-1">Time remaining</div><div class="display-1 fw-bold" style="color:var(--cricket-lime);" x-text="formattedTimer"></div></div><div class="col-md-5 mt-3 mt-md-0"><div class="small text-white-50 mb-2">Draft progress</div><div class="d-flex justify-content-between small mb-2"><span x-text="`${state.summary?.selected ?? 0} selected`"></span><span x-text="`${state.summary?.total ?? 0} total picks`"></span></div><div class="progress" style="height:.55rem;background:rgba(255,255,255,.15);"><div class="progress-bar" style="background:var(--cricket-lime);" :style="`width: ${state.summary?.total ? ((state.summary.selected / state.summary.total) * 100) : 0}%`"></div></div></div></div></div></div><div class="col-xl-4"><div class="cricket-surface p-4 h-100"><p class="cricket-kicker mb-2">At a glance</p><h2 class="h4 fw-bold mb-4">Draft scoreboard</h2><div class="vstack gap-2"><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Completed</span><strong class="text-success" x-text="state.summary?.selected ?? 0"></strong></div><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">On the clock</span><strong x-text="state.summary?.active ?? 0"></strong></div><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Pending</span><strong x-text="state.summary?.pending ?? 0"></strong></div><div class="cricket-surface-soft p-3 d-flex justify-content-between"><span class="text-secondary">Skipped</span><strong x-text="state.summary?.skipped ?? 0"></strong></div></div><div class="small text-secondary mt-4"><i class="fa-solid fa-arrows-rotate text-success me-2"></i>Squads refresh automatically.</div></div></div></div>

        <div class="cricket-surface p-4 p-lg-5 mb-4"><div class="d-flex flex-column flex-md-row align-items-md-end justify-content-between gap-3 mb-4"><div><p class="cricket-kicker mb-2">Selected squads</p><h2 class="h3 fw-bold mb-1">Who has been picked?</h2><p class="text-secondary mb-0">Team-wise selections recorded by the live draft engine.</p></div><div class="d-flex align-items-center gap-2"><span class="badge text-bg-light" x-text="`${state.summary?.selected ?? 0} players selected`"></span><a href="{{ route('public.reports.pdf', [$tournament, 'squads']) }}" class="btn btn-sm btn-outline-success"><i class="fa-solid fa-download me-1"></i>All squads PDF</a></div></div><div class="row g-4" x-show="teamSquads.length"><template x-for="team in teamSquads" :key="team.id"><div class="col-lg-6"><div class="cricket-surface-soft p-4 h-100"><div class="d-flex align-items-center justify-content-between gap-3 mb-3"><div class="d-flex align-items-center gap-3"><span class="cricket-brand-mark"><i class="fa-solid fa-shield"></i></span><div><h3 class="h4 fw-bold mb-1" x-text="team.name"></h3><div class="small text-secondary" x-text="`${team.picks.length} player${team.picks.length === 1 ? '' : 's'} picked`"></div></div></div><span class="badge text-bg-success" x-text="team.picks.length"></span></div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Pick</th><th>Player</th><th>Role</th></tr></thead><tbody><template x-for="pick in team.picks" :key="pick.pick_number"><tr><td><span class="badge rounded-circle text-bg-success" x-text="pick.pick_number"></span></td><td class="fw-bold" x-text="pick.player?.full_name || 'Player selected'"></td><td class="text-secondary" x-text="pick.player?.playing_role || '—'"></td></tr></template></tbody></table></div></div></div></template></div><div class="cricket-surface-soft p-4 text-center" x-show="!teamSquads.length"><i class="fa-solid fa-users text-success fs-2 mb-3"></i><h3 class="h5 fw-bold">No player has been selected yet</h3><p class="text-secondary mb-0">The first confirmed pick will appear here in real time.</p></div></div>

        <div class="cricket-surface p-4 p-lg-5"><div class="d-flex flex-column flex-md-row align-items-md-end justify-content-between gap-3 mb-4"><div><p class="cricket-kicker mb-2">Pick-by-pick</p><h2 class="h3 fw-bold mb-1">Draft history</h2><p class="text-secondary mb-0">The full selection sequence, exactly as recorded by the server.</p></div><span class="badge text-bg-light" x-text="`${state.summary?.selected ?? 0}/${state.summary?.total ?? 0} completed`"></span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Pick</th><th>Round</th><th>Team</th><th>Player</th><th>Status</th></tr></thead><tbody><template x-for="pick in state.picks" :key="pick.pick_number"><tr><td><span class="badge rounded-circle p-2" :class="pick.status === 'selected' ? 'text-bg-success' : (pick.status === 'active' ? 'text-bg-warning' : 'text-bg-light')" x-text="pick.pick_number"></span></td><td class="text-secondary" x-text="pick.round"></td><td class="fw-bold" x-text="pick.team?.name"></td><td x-text="pick.player?.full_name || (pick.status === 'active' ? 'On the clock' : '—')"></td><td><span class="badge" :class="pick.status === 'selected' ? 'text-bg-success' : (pick.status === 'active' ? 'text-bg-warning' : 'text-bg-light')" x-text="pick.status"></span></td></tr></template></tbody></table></div><div class="alert alert-light border mt-4 mb-0" x-show="error" x-text="error"></div></div>
    </main>
    <script>
        function publicDraft(initialState, stateUrl) { return { state: initialState, stateUrl, remaining: initialState.timer?.remaining_seconds ?? null, timerDeadline: initialState.timer?.expires_at ? Date.parse(initialState.timer.expires_at) : null, serverOffsetMs: initialState.timer?.server_now ? Date.parse(initialState.timer.server_now) - Date.now() : 0, error: '', init() { this.syncTimer(); window.setInterval(() => this.syncTimer(), 250); window.setInterval(() => this.poll(), 2000); }, syncTimer() { if (this.timerDeadline === null || !['live', 'expired'].includes(this.state.status)) return; this.remaining = Math.max(0, Math.ceil((this.timerDeadline - (Date.now() + this.serverOffsetMs)) / 1000)); }, syncServerClock(payload, requestStartedAt = null, responseReceivedAt = null) { const serverNow = payload.timer?.server_now ? Date.parse(payload.timer.server_now) : null; if (Number.isFinite(serverNow)) { const midpoint = requestStartedAt !== null && responseReceivedAt !== null ? (requestStartedAt + responseReceivedAt) / 2 : Date.now(); this.serverOffsetMs = serverNow - midpoint; } }, get formattedTimer() { if (this.remaining === null) return '--:--'; return `${Math.floor(this.remaining / 60).toString().padStart(2, '0')}:${Math.floor(this.remaining % 60).toString().padStart(2, '0')}`; }, get teamSquads() { const squads = {}; this.state.picks.filter(pick => pick.status === 'selected' && pick.team).forEach(pick => { const id = pick.team.id; if (!squads[id]) squads[id] = { id, name: pick.team.name, picks: [] }; squads[id].picks.push(pick); }); return Object.values(squads); }, async poll() { if (document.hidden) return; try { const requestStartedAt = Date.now(); const response = await fetch(this.stateUrl, { headers: { 'Accept': 'application/json' } }); const responseReceivedAt = Date.now(); if (!response.ok) return; const payload = await response.json(); this.syncServerClock(payload, requestStartedAt, responseReceivedAt); if (payload.revision !== this.state.revision) { this.state = payload; this.timerDeadline = payload.timer?.expires_at ? Date.parse(payload.timer.expires_at) : null; this.syncTimer(); } } catch (error) { this.error = 'Live connection interrupted. Retrying automatically.'; } } }; }
    </script>
</x-public-layout>
